'use strict';
// Search: ranking, loose multi-word matching, and the deliberate operators.
// Covers SCN-001 (search across title/link/summary), SCN-015 (into the saved copy),
// SCN-016 (ranking + loose AND), SCN-017 (phrase / either / exclude / literal-via-quotes).
// Scope filtering (SCN-018) and archived-exclusion (SCN-008) are applied by the caller
// before handing records here.

// Field weights: a hit in the title/summary/label is "strong" and always outranks a
// hit found only in the page body (SCN-016).
const WEIGHTS = { title: 100, summary: 40, labels: 40, url: 20, body: 10 };
const STRONG_FIELDS = new Set(['title', 'summary', 'labels']);
const EXCLUDE_WORDS = new Set(['not', 'without', 'except']);

function fieldsOf(rec) {
  return {
    title: rec.title || '',
    summary: rec.summary || '',
    labels: (rec.labels || []).join(' '),
    url: rec.url || '',
    body: rec.copyText || '',
  };
}

// Parse a query string into AND-groups (each group = OR alternatives) plus negatives.
// - Double quotes => an exact phrase, AND the escape for a literal little word ("or"/"not").
// - Bare "or" joins the previous and next term into one either-group.
// - Bare "and" is ignored (AND is already the default).
// - Bare "not"/"without"/"except", or a leading "-", make the next term a negative.
function parseQuery(q) {
  const raw = String(q || '').match(/-?"[^"]*"|\S+/g) || [];
  const groups = [];
  const negs = [];
  let pendingOr = false;
  let pendingNeg = false;

  for (const r0 of raw) {
    let r = r0;
    let neg = false;
    let phrase = false;
    if (r[0] === '-') { neg = true; r = r.slice(1); }
    if (r[0] === '"') { phrase = true; r = r.replace(/^"|"$/g, ''); }
    const text = r.toLowerCase().trim();
    if (!text) continue;

    if (!phrase && !neg) {
      if (text === 'or' && groups.length) { pendingOr = true; continue; }
      if (text === 'and') { continue; }
      if (EXCLUDE_WORDS.has(text)) { pendingNeg = true; continue; }
    }
    if (neg || pendingNeg) { negs.push({ text, phrase }); pendingNeg = false; continue; }

    const tok = { text, phrase };
    if (pendingOr && groups.length) { groups[groups.length - 1].push(tok); pendingOr = false; }
    else groups.push([tok]);
  }
  return { groups, negs };
}

// Score one record against a parsed query. Returns null if it does not match
// (a required group unsatisfied, or a negative present). Otherwise {total, why, strong}.
function scoreRecord(rec, parsed) {
  const f = fieldsOf(rec);
  const flat = Object.values(f).join(' � ').toLowerCase();
  for (const n of parsed.negs) {
    if (flat.includes(n.text)) return null;
  }
  let total = 0;
  const why = [];
  for (const grp of parsed.groups) {
    let best = 0, bestField = null, bestTerm = null;
    for (const alt of grp) {
      for (const k in f) {
        if (f[k].toLowerCase().includes(alt.text)) {
          if (WEIGHTS[k] > best) { best = WEIGHTS[k]; bestField = k; bestTerm = alt.text; }
        }
      }
    }
    if (best === 0) return null; // every AND-group must be satisfied by some alternative
    total += best;
    why.push({ term: bestTerm, field: bestField });
  }
  const strong = why.some((w) => STRONG_FIELDS.has(w.field));
  return { total, why, strong };
}

function allTerms(parsed) {
  const s = new Set();
  parsed.groups.forEach((g) => g.forEach((t) => s.add(t.text)));
  return [...s];
}

// Short excerpt of the body around the first matched term (for legible body-only hits, SCN-016).
function snippet(rec, terms) {
  const body = rec.copyText || '';
  const low = body.toLowerCase();
  for (const t of terms) {
    const i = low.indexOf(t);
    if (i >= 0) {
      const s = Math.max(0, i - 40);
      const e = Math.min(body.length, i + 90);
      return (s > 0 ? '…' : '') + body.slice(s, e).trim() + (e < body.length ? '…' : '');
    }
  }
  return '';
}

// Rank a set of records for a query. Strong matches first, body-only matches after
// (the caller can draw the "further down on purpose" divider at firstWeakIndex).
function searchRecords(records, q) {
  const parsed = parseQuery(q);
  const terms = allTerms(parsed);
  const scored = [];
  for (const rec of records) {
    const s = scoreRecord(rec, parsed);
    if (s) scored.push({ rec, ...s });
  }
  scored.sort((a, b) => b.total - a.total || String(a.rec.savedAt) < String(b.rec.savedAt) ? 1 : -1);
  // stable-ish secondary sort by savedAt desc handled above; normalize:
  scored.sort((a, b) => (b.total - a.total) || (String(b.rec.savedAt).localeCompare(String(a.rec.savedAt))));
  const results = scored.map((x) => ({
    id: x.rec.id,
    total: x.total,
    strong: x.strong,
    why: x.why,
    snippet: x.strong ? '' : snippet(x.rec, terms),
  }));
  const firstWeakIndex = results.findIndex((r) => !r.strong);
  return { parsed, terms, results, firstWeakIndex };
}

// Describe how the query was interpreted, in plain words (drives the "Reading your search as" bar).
function describe(parsed) {
  const chips = [];
  for (const g of parsed.groups) {
    if (g.length > 1) chips.push({ kind: 'either', text: g.map((t) => t.text).join(' / ') });
    else if (g[0].phrase) chips.push({ kind: 'phrase', text: g[0].text });
    else chips.push({ kind: 'word', text: g[0].text });
  }
  for (const n of parsed.negs) chips.push({ kind: 'without', text: n.text });
  const special = parsed.groups.some((g) => g.length > 1 || g[0].phrase) || parsed.negs.length > 0;
  return { chips, special };
}

module.exports = { WEIGHTS, parseQuery, scoreRecord, searchRecords, describe, allTerms, snippet };

