  const re = new RegExp(name + '\\s*=\\s*"([^"]*)"', 'i');
  const m = attrs.match(re);
  return m ? decodeEntities(m[1]) : null;
}

function stripTags(s) {
  return decodeEntities(String(s).replace(/<[^>]+>/g, ''));
}

function decodeEntities(s) {
  return String(s)
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
