input.content:
* { box-sizing: border-box; }
body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; margin: 0; background: #f4f5f7; color: #1a1a2e; }
header { background: #fff; border-bottom: 1px solid #e3e5e8; padding: 16px 28px; position: sticky; top: 0; z-index: 5; }
.topline { display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px; }
h1 { font-size: 20px; margin: 0; }
.hbtns { display: flex; gap: 8px; }
.hbtn { font-size: 13px; font-weight: 600; padding: 8px 14px; border-radius: 8px; border: 1px solid #cfd3d8; background: #fff; color: #3f4b5b; cursor: pointer; }
.hbtn:hover { background: #eef1f5; }
.savebar { display: flex; gap: 8px; align-items: center; }
.savebar input.url { flex: 1; padding: 11px 14px; font-size: 15px; border: 1px solid #cfd3d8; border-radius: 8px; }
.savebar input.url.err { border-color: #d9534f; background: #fdf3f2; }
.tr-toggle { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; color: #6b6455; background: #fdf7e3; border: 1px solid #ecd98f; border-radius: 8px; padding: 10px 12px; cursor: pointer; white-space: nowrap; }
.tr-toggle input { accent-color: #b8860b; width: 15px; height: 15px; }
.savebar button.save { padding: 11px 20px; font-size: 15px; font-weight: 600; background: #2f6fed; color: #fff; border: none; border-radius: 8px; cursor: pointer; }
.savebar button.save:hover { background: #235bce; }
.saveerr { color: #c0392b; font-size: 13px; margin: 8px 2px 0; min-height: 0; }

main { max-width: 900px; margin: 0 auto; padding: 22px 28px 60px; }
.searchrow { position: relative; margin-bottom: 8px; }
.searchrow input { width: 100%; padding: 12px 14px 12px 42px; font-size: 15px; border: 1px solid #cfd3d8; border-radius: 10px; background: #fff; }
.searchrow .mag { position: absolute; left: 15px; top: 50%; transform: translateY(-50%); color: #9aa1ab; font-size: 16px; }
.help { font-size: 12px; color: #9aa1ab; margin: 0 2px 12px; }
.help code { background: #eef1f5; border-radius: 4px; padding: 0 5px; color: #1c4fbf; }
.scope { font-size: 13px; margin: 0 0 12px; padding: 8px 13px; border-radius: 8px; background: #eef4ff; border: 1px solid #cfe0ff; color: #26456e; display: none; }
.scope.show { display: block; }
.scope a { color: #2f6fed; cursor: pointer; font-weight: 600; }
.views { display: flex; gap: 8px; margin-bottom: 14px; flex-wrap: wrap; }
.view { display: inline-flex; align-items: center; gap: 7px; font-size: 13.5px; font-weight: 600; padding: 8px 15px; border-radius: 9px; border: 1px solid #cfd3d8; background: #fff; color: #3f4b5b; cursor: pointer; }
.view:hover { background: #eef1f5; }
.view.active { background: #1a1a2e; border-color: #1a1a2e; color: #fff; }
.view.toread.active { background: #b8860b; border-color: #b8860b; }
.view.archived.active { background: #566072; border-color: #566072; }
.view .n { font-size: 12px; background: rgba(0,0,0,.09); border-radius: 999px; padding: 1px 8px; }
.view.active .n { background: rgba(255,255,255,.22); }
.labelbar { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 14px; align-items: center; }
.labelbar .lead { font-size: 12.5px; color: #6b7280; }
.pill { font-size: 12.5px; padding: 5px 12px; border-radius: 999px; border: 1px solid #cfd3d8; background: #fff; color: #4b5563; cursor: pointer; }
.pill:hover { background: #eef1f5; }
.pill.active { background: #2f6fed; border-color: #2f6fed; color: #fff; }
.interp { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; margin-bottom: 10px; }
.interp .lab { font-size: 12px; color: #9aa1ab; }
.icap { font-size: 11.5px; font-weight: 600; border-radius: 999px; padding: 3px 10px; }
.icap.phrase { color: #7a4bcc; background: #f1eafd; border: 1px solid #ddc9f7; }
.icap.either { color: #1c7f8f; background: #e2f6f9; border: 1px solid #bfe8ee; }
.icap.without { color: #b13b36; background: #fdecea; border: 1px solid #f2c4c0; }
.icap.word { color: #3f4b5b; background: #eef1f5; border: 1px solid #e0e3e8; }
.count { color: #6b7280; font-size: 13px; margin: 0 0 14px 2px; }

.card { display: flex; gap: 14px; background: #fff; border: 1px solid #e3e5e8; border-radius: 12px; padding: 14px; margin-bottom: 12px; position: relative; animation: pop .2s ease; }
@keyframes pop { from { opacity: 0; transform: translateY(5px);} to { opacity: 1; transform: none; } }
.card.toread { border-left: 4px solid #d4a017; }
.card.archived { background: #fbfbfc; }
.card.dead { border-left: 4px solid #9aa1ab; background: #fbfbfc; }
.card.needsinfo { border-left: 4px solid #d9534f; }
.card.flash { box-shadow: 0 0 0 3px rgba(255,180,0,.5); }
.rankno { position: absolute; left: -7px; top: 13px; width: 20px; text-align: center; font-size: 12px; font-weight: 700; color: #b3b8c0; }
.clickable { cursor: pointer; } .clickable:hover .title { text-decoration: underline; }
.thumb { width: 104px; height: 72px; flex: none; border-radius: 8px; object-fit: cover; background: #e9ebef; }
.thumb.ph { display: flex; align-items: center; justify-content: center; color: #b3b8c0; font-size: 24px; background: #eef0f3; border: 1px dashed #cfd3d8; }
.thumb.dead { filter: grayscale(1); opacity: .5; }
.body { min-width: 0; flex: 1; }
.titlerow { display: flex; align-items: center; gap: 8px; margin: 2px 0 4px; flex-wrap: wrap; }
.badge { font-size: 10.5px; font-weight: 700; border-radius: 999px; padding: 2px 9px; }
.badge.tr { color: #8a6d0b; background: #fdf3d3; border: 1px solid #ecd98f; }
.badge.ar { color: #4a5468; background: #e7eaef; border: 1px solid #ccd2db; }
.badge.red { color: #b13b36; background: #fdecea; border: 1px solid #f2c4c0; }
.badge.grey { color: #566072; background: #e7eaef; border: 1px solid #ccd2db; }
.title { font-size: 16px; font-weight: 600; } .title.untitled { color: #9aa1ab; font-style: italic; }
.url { font-size: 12px; color: #2f6fed; margin: 0 0 4px; word-break: break-all; }
.meta { font-size: 11.5px; color: #9aa1ab; margin-bottom: 6px; }
.desc { font-size: 13.5px; color: #4b5563; margin: 0 0 8px; line-height: 1.45; }
.why { display: flex; flex-wrap: wrap; gap: 6px; }
