.banner { font-size: 13px; padding: 11px 34px; }
.banner.gone { background: #fff6e6; color: #8a5b00; border-bottom: 1px solid #f0dca8; }
.banner.copy { background: #eafaf0; color: #1a6b36; border-bottom: 1px solid #cde9d7; }
.reader { padding: 28px 40px 44px; max-width: 680px; }
.reader h2 { margin: 0 0 6px; font-size: 23px; }
.reader .meta { font-size: 12.5px; color: #9aa1ab; margin-bottom: 20px; }
.reader p { color: #2b3140; line-height: 1.7; font-size: 15.5px; margin: 0 0 15px; }
.reader .visit { display: inline-block; margin-bottom: 18px; background: #2f6fed; color: #fff; text-decoration: none; border-radius: 8px; padding: 9px 16px; font-size: 14px; font-weight: 600; }
.gonebox { text-align: center; padding: 50px 40px; } .gonebox .big { font-size: 40px; } .gonebox h2 { margin: 8px 0; } .gonebox p { color: #6b7280; }
.gonebox .cta { margin-top: 16px; background: #1a7a3c; color: #fff; border: none; border-radius: 8px; padding: 10px 18px; font-weight: 600; cursor: pointer; }

.modal { position: fixed; inset: 0; background: rgba(0,0,0,.45); z-index: 50; display: none; align-items: center; justify-content: center; padding: 24px; }
.modal.show { display: flex; }
.sheet { background: #fff; width: 100%; max-width: 540px; border-radius: 14px; overflow: hidden; box-shadow: 0 20px 60px rgba(0,0,0,.35); }
.sheet h3 { margin: 0; padding: 18px 22px; border-bottom: 1px solid #eceef1; font-size: 17px; }
.sheet .in { padding: 20px 22px; }
.sheet p { color: #4b5563; line-height: 1.55; font-size: 14px; margin: 0 0 14px; }
.filepick { border: 2px dashed #cfd3d8; border-radius: 10px; padding: 22px; text-align: center; color: #6b7280; font-size: 14px; cursor: pointer; background: #fafbfc; }
.filepick:hover { background: #f2f5f9; border-color: #a9c2f2; }
.filepick .fname { color: #1a1a2e; font-weight: 600; margin-top: 8px; }
.foldopt { display: flex; gap: 10px; align-items: flex-start; margin: 14px 0 4px; font-size: 13.5px; color: #3f4b5b; }
