.bar > span { display: block; height: 100%; width: 0; background: #2f6fed; transition: width .15s linear; }
.prog { font-size: 13px; color: #6b7280; }
.summary { font-size: 14px; color: #1a1a2e; line-height: 1.7; }
.summary b { color: #1a7a3c; } .summary .warn { color: #8a5b00; }
.actions { padding: 14px 22px; border-top: 1px solid #eceef1; display: flex; gap: 8px; justify-content: flex-end; }
.actions button { font-size: 14px; font-weight: 600; border-radius: 8px; padding: 9px 16px; cursor: pointer; border: 1px solid #cfd3d8; background: #fff; color: #3f4b5b; }
.actions button.primary { background: #2f6fed; color: #fff; border-color: #2f6fed; }

