cd /work
cp /work/MyBookmarks.html /work/prototypes/MyBookmarks.html
cmp -s /work/MyBookmarks.html /work/prototypes/MyBookmarks.html && echo "synced to prototypes: byte-for-byte" || echo "SYNC MISMATCH"
python3 - <<'PY'
import re
html=open('MyBookmarks.html',encoding='utf-8').read()
open('/tmp/appcheck2.js','w').write(re.search(r'<script>(.*)</script>',html,re.S).group(1))
PY
node --check /tmp/appcheck2.js && echo "✅ syntax OK after changes" || echo "❌ syntax error"
# sanity-test the new relTime helper (pure, no browser)
node -e '
const s=require("fs").readFileSync("/tmp/appcheck2.js","utf8");
const m=s.match(/function relTime[\s\S]*?\n}\n/); eval(m[0]);
const iso=d=>new Date(d).toISOString();
const now=new Date();
console.log("today ->", relTime(iso(now)));
console.log("yesterday ->", relTime(iso(new Date(Date.now()-864e5))));
console.log("3 days ->", relTime(iso(new Date(Date.now()-3*864e5))));
console.log("never ->", relTime(null));
'
echo "--- confirm both new safety features are present in the delivered file ---"
grep -c "aren't showing here" /work/prototypes/MyBookmarks.html && echo "  ✓ reassuring empty screen"
grep -c "Last backup:" /work/prototypes/MyBookmarks.html && echo "  ✓ last-backup status line"
